import type { EngineInterface, Register } from 'claude-code'

import { block, MACROS, macrosIn, preview, size, truncate } from './lib'
import type { Macro } from './lib'

type $ = EngineInterface

// Quem tiver a área de transferência responde primeiro: macOS, Wayland, X11 e WSL.
const CLIPBOARD = [
  ['pbpaste'],
  ['wl-paste', '--no-newline'],
  ['xclip', '-o', '-selection', 'clipboard'],
  ['powershell.exe', '-NoProfile', '-Command', 'Get-Clipboard'],
]

// Prompts escritos por uma pessoa: no terminal, pelo celular (Remote Control) ou no `claude -p`.
// Mensagens de outras sessões e de tarefas em segundo plano ficam de fora.
const HUMAN = new Set(['composer', 'bridge', 'sdk'])

/** Roda um comando (sem shell) e devolve a saída, ou undefined se falhou. */
async function run($: $, argv: readonly string[]): Promise<string | undefined> {
  const ran = await $.process.run(argv, { timeoutMs: 10_000 }).catch(() => undefined)

  return ran?.exitCode === 0 ? ran.stdout : undefined
}

const CLIP_QUESTION = 'Anexar ao prompt a área de transferência'
const CLIP_ATTACH = 'Anexar'
const CLIP_DECLINE = 'Não anexar'
const CLIP_REFUSED = '(a pessoa preferiu não anexar a área de transferência)'

/**
 * A área de transferência pode ter uma senha ou um token: só vai ao modelo com
 * um clique, vendo o começo do que está lá. Diálogo fechado ou `-p` é recusa.
 */
async function confirmClip($: $, text: string): Promise<boolean> {
  const answer = await $.ui
    // Why: "Não anexar" primeiro, para qualquer escolha padrão cair na recusa.
    .ask(`${CLIP_QUESTION} (${size(text)}: "${preview(text)}")?`, { header: '@clip', options: [CLIP_DECLINE, CLIP_ATTACH] })
    .catch(() => '')

  return answer === CLIP_ATTACH
}

/** O conteúdo de cada macro. */
async function expand($: $, macro: Macro, limit: number): Promise<string> {
  if (macro === 'clip') {
    for (const argv of CLIPBOARD) {
      const text = await run($, argv)
      if (text !== undefined) return (await confirmClip($, text)) ? text.replace(/\r\n/g, '\n') : CLIP_REFUSED
    }
    return '(não consegui ler a área de transferência)'
  }

  const branch = await run($, ['git', 'rev-parse', '--abbrev-ref', 'HEAD'])
  if (branch === undefined) return '(esta pasta não é um repositório git)'

  if (macro === 'branch') {
    const log = (await run($, ['git', 'log', '--oneline', '-5'])) ?? ''
    return `Branch: ${branch.trim()}\n\nÚltimos commits:\n${log}`
  }
  if (macro === 'log') return (await run($, ['git', 'log', '--oneline', '-15'])) ?? ''

  const staged = (await run($, ['git', 'diff', '--staged'])) ?? ''
  const unstaged = (await run($, ['git', 'diff'])) ?? ''
  const diff = [staged && `# no stage\n${staged}`, unstaged && `# fora do stage\n${unstaged}`].filter(Boolean).join('\n')

  return diff === '' ? '(nenhuma mudança)' : '```diff\n' + truncate(diff, limit) + '\n```'
}

export const register: Register = (on, options) => {
  const limit = Number(options.limiteDiff ?? 20_000) || 20_000

  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'atalhos', description: 'Lista os macros (@diff, @branch, @log, @clip) que o prompt aceita' })

    return next(e)
  })

  on('command.run', { command: 'atalhos' }, () => ({
    text: ['Escreva no prompt e o conteúdo vai junto para o modelo:', ...Object.entries(MACROS).map(([name, what]) => `  @${name}  ${what}`)].join('\n'),
  }))

  // O coração do mod: antes do modelo ver o prompt, cada macro vira um bloco de contexto.
  on('prompt.submit', async ($, e, next) => {
    const macros = macrosIn(e.text)
    if (!HUMAN.has(e.origin.kind) || macros.length === 0) return next(e)

    const blocks = await Promise.all(macros.map(async macro => block(macro, await expand($, macro, limit))))
    $.ui.toast(`📎 atalhos: anexei ${macros.map((macro, i) => `@${macro} (${size(blocks[i] ?? '')})`).join(', ')}`)

    // O texto digitado fica igual; o conteúdo entra como contexto, que a pessoa não vê.
    return next({ ...e, context: [...(e.context ?? []), ...blocks] })
  })

  // Só um clique da pessoa anexa: o diálogo que se resolveu sozinho por ausência vale como recusa.
  on('tool.call', { tool: 'AskUserQuestion' }, async ($, e, next) => {
    const result = await next(e)
    const answered = (result as { result?: { answers?: Record<string, string>; afkTimeoutMs?: number } }).result
    if (answered?.afkTimeoutMs === undefined || answered.answers === undefined) return result
    const answers = Object.fromEntries(
      Object.entries(answered.answers).map(([question, answer]) => [question, question.startsWith(CLIP_QUESTION) ? CLIP_DECLINE : answer]),
    )

    return { ...result, result: { ...answered, answers } } as typeof result
  })
}

