// Lógica pura do atalhos, separada para os testes.

export type Macro = 'diff' | 'branch' | 'log' | 'clip'

export const MACROS: Record<Macro, string> = {
  diff: 'as mudanças do working tree e do stage (git diff)',
  branch: 'o branch atual e os últimos 5 commits',
  log: 'os últimos 15 commits (git log --oneline)',
  clip: 'o conteúdo da área de transferência',
}

/**
 * Os macros que aparecem no texto, na ordem e sem repetir. Só conta `@nome`
 * no começo ou depois de espaço, para não pegar e-mails (`eu@diff.com`); entre
 * crases (`` `@clip` ``) ou com barra (`\@clip`) é texto, não macro.
 */
export function macrosIn(text: string): Macro[] {
  const found: Macro[] = []
  const prose = text.replace(/```[\s\S]*?```|`[^`\n]*`/g, ' ')
  for (const match of prose.matchAll(/(?:^|\s)@(\w+)\b/g)) {
    const name = match[1] as Macro
    if (name in MACROS && !found.includes(name)) found.push(name)
  }

  return found
}

/** Corta textos grandes e avisa o modelo de que o corte aconteceu. */
export function truncate(text: string, limit: number): string {
  if (text.length <= limit) return text

  return `${text.slice(0, limit)}\n… (cortado: mostrei ${limit} de ${text.length} caracteres)`
}

/** O bloco de contexto de um macro: cabeçalho e conteúdo. */
export function block(macro: Macro, body: string): string {
  return `### @${macro}: ${MACROS[macro]}\n\n${body.trim() === '' ? '(vazio)' : body.trim()}`
}

/** O começo de um texto numa linha só, para a pessoa reconhecer o que vai anexar. */
export function preview(text: string, length = 60): string {
  const line = text.replace(/\s+/g, ' ').trim()

  return line.length <= length ? line : `${line.slice(0, length)}…`
}

/** "3,2 KB" para o toast. */
export function size(text: string): string {
  return text.length < 1024 ? `${text.length} B` : `${(text.length / 1024).toFixed(1).replace('.', ',')} KB`
}

